rentSeconds: number;\r\n}\r\n\r\nexport type QueryOrderSuccessParams = {\r\n  orderNo: string;\r\n  validityPeriod: string; \r\n  availableRegions: string[]; \r\n  pkgName: string;\r\n  pkgCategory: string;\r\n  pkgType: string;\r\n  msisdn: string;\r\n  iccid: string;\r\n  payTypeVos: any[]; \r\n  currencyCode: string;\r\n  payAmount: string; \r\n  createTime: string; \r\n  payTime: string; \r\n  status: string;\r\n  payCurrencyAmount: string;\r\n  symbol: string;\r\n  signPosition: string;\r\n  payType: string;\r\n  rechargeNo: string;\r\n}\r\n\r\n// 问题反馈类型\r\nexport type FeedbackItem = {\r\n  id: number\r\n  feedbackNo: string\r\n  feedbackType: string\r\n  feedbackContent: string\r\n  status: string\r\n  createTime: string\r\n  userPhone: string\r\n  imgOssUrl: string\r\n  orderNo: string\r\n  packageName: string\r\n  replyContent: string\r\n  rechargeNo: string\r\n}\r\n\r\n// 问题反馈消息项\r\nexport type FeedbackMessageItem = {\r\n  sendType: string\r\n  time: string\r\n  replyContent: string\r\n  imgOssUrl: string\r\n}\r\n\r\n// 问题反馈详情\r\nexport type FeedbackDetail = {\r\n  id: number\r\n  feedbackNo: string\r\n  feedbackType: string\r\n  status: string\r\n  subTime: string\r\n  userPhone: string\r\n  imgOssUrl: string\r\n  feedbackContentList: FeedbackMessageItem[]\r\n  rechargeNo: string\r\n}","/** 登录响应数据 */\r\nexport type LoginData = {\r\n  id: number\r\n  token: string\r\n  access_token: string\r\n  refreshToken: string\r\n  userId: number\r\n  nickname: string\r\n}\r\n\r\n/** 国家数据 */\r\nexport type CountryData = {\r\n  fullName: string\r\n  letterCode: string\r\n}\r\n\r\n/** 租户配置数据 */\r\nexport type TenantInfoData = {\r\n  rechargeTip: string\r\n  servicePhone: string\r\n  serviceQrcode: string\r\n  wxAuditHide: string\r\n  wxAuditHideNo: string\r\n  wxGetPhoneLogin: string\r\n  wxMiniPayType: string\r\n  wxPayClass: string\r\n  h5IsPullMini: string\r\n  h5PayType: string\r\n  serviceJumpUrl: string\r\n}\r\n\r\n/** 查询卡列表参数 */\r\nexport type QueryCardListParams 