{"version":3,"file":"types.js","sources":["api/types.uts"],"sourcesContent":["/** 登录响应数据 */\nexport type LoginData = {\n  id: number\n  token: string\n  access_token: string\n  refreshToken: string\n  userId: number\n  nickname: string\n}\n\n/** 国家数据 */\nexport type CountryData = {\n  fullName: string\n  letterCode: string\n}\n\n/** 租户配置数据 */\nexport type TenantInfoData = {\n  rechargeTip: string\n  servicePhone: string\n  serviceQrcode: string\n  wxAuditHide: string\n  wxAuditHideNo: string\n  wxGetPhoneLogin: string\n  wxMiniPayType: string\n  wxPayClass: string\n  h5IsPullMini: string\n  h5PayType: string\n  serviceJumpUrl: string\n}\n\n/** 查询卡列表参数 */\nexport type QueryCardListParams = {\n  rechargeNo?: string\n  status: string\n  isSort?: boolean\n}\n\n/** 卡列表统计数据 */\nexport type CardListSumData = {\n  all: number\n  inUse: number\n  inNotUse: number\n}\n\n// 卡片数据类型\nexport type CardItem = {\n\tid: number\n\tcardNumber: string\n\ticcid: string\n\ttag: string\n\tstatus: string\n\tcurrentPackage: string\n\texpireDate: string\n\tusedTraffic: string\n\ttotalTraffic: string\n\tcurrentCycle: string\n  usedPeriod: string\n  totalPeriod: string\n}\n\n/** 查询卡列表返回数据 */\nexport type QueryCardListData = {\n\tlist: CardItem[]\n}\n\n// 卡片详情数据类型\nexport type PkgXcxVo = {\n  pkgId: string;\n  pkgName: string;\n  pkgCategory: string;\n  pkgType: string;\n  validityPeriod: string | null;\n  pkgFlow: string | null;\n  crossedOutPrice: string;\n  sellingPrice: string;\n  objectMap: objectMapType;\n};\n\nexport type objectMapType = {\n  rechargeTip: string;\n  servicePhone: string;\n  serviceQrcode: string;\n}\n\nexport type RechargeData = {\n  rechargeNo: string;\n  pkgName: string;\n  status: string;\n  statusStr: string;\n  effectiveTime: string;\n  expirationTime: string | null;\n  pkgFlow: string | null;\n  usedFlow: string | null;\n  unUsedFlow: string | null;\n  usedPeriod: string | null;\n  totalPeriod: string | null;\n  currentPeriodStartTime: string | null;\n  currentPeriodEndTime: string | null;\n  isBind: boolean;\n  pkgXcxVos: PkgXcxVo[];\n};\n\nexport type CardDetail = {\n  code: number;\n  msg: string;\n  data: RechargeData;\n};\n\n/** 绑定卡参数 */\nexport type BindCard = {\n  rechargeNo: string\n}\n\n/** 查询套餐信息列表参数 */\nexport type PkgInfoListParams = {\n  rechargeNo: string,\n  status: string\n}\n\nexport type PkgInfoItem = {\n\t\tid: string\n\t\tname: string\n\t\tstatus: string\n\t\tstatusText: string\n\t\ttagType: string\n\t\tstartTime: string\n\t\tendTime: string\n\t\ttotalFlow: string\n\t\tusedFlow: string\n\t\tleftFlow: string\n}\n\n// 查询订单列表Xcx参数\nexport type QueryOrderListXcxParams = {\n\trechargeNo: string,\n}\n// 查询订单列表Xcx返回数据\nexport type QueryOrderListXcxData = {\n\tcode: number;\n\tmsg: string;\n\trows: OrderListXcxItem[];\n  total: number;\n}\n\nexport type OrderListXcxItem = {\n  id: number;\n  orderNo: string;\n  rechargeNo: string;\n  iccid?: string;\n  pkgName: string;\n  createTime: string;\n  status: string;\n  payCurrencyAmount: string;\n}\n\n\nexport type Refund = {\n    property1: string;\n    property2: string;\n}\n\nexport type QueryOrderDetailXcxData = {\n  orderNo: string;\n  rechargeNo: string;\n  pkgName: string;\n  pkgCategory: string;\n  pkgType: string;\n  pkgFlow: number;\n  validityPeriod: string;\n  startDate: string;\n  endDate: string;  \n  status: string;\n  pkgRefundStatus: string;\n  orderAmount: number;\n  payAmount: number;\n  orderCreateTime: string;\n  payTime: string;        \n  refunds: Refund[];\n  cancelTime: string;     \n  payFailTime: string;    \n  payFailReason: string;\n  usageInstructions: string;\n  currentSeconds: number;\n}\n\nexport type QueryOrderSuccessParams = {\n  orderNo: string;\n  validityPeriod: string; \n  availableRegions: string[]; \n  pkgName: string;\n  pkgCategory: string;\n  pkgType: string;\n  msisdn: string;\n  iccid: string;\n  payTypeVos: any[]; \n  currencyCode: string;\n  payAmount: string; \n  createTime: string; \n  payTime: string; \n  status: string;\n  payCurrencyAmount: string;\n  symbol: string;\n  signPosition: string;\n  payType: string;\n  rechargeNo: string;\n}\n\n// 问题反馈类型\nexport type FeedbackItem = {\n  id: number\n  feedbackNo: string\n  feedbackType: string\n  feedbackContent: string\n  status: string\n  createTime: string\n  userPhone: string\n  imgOssUrl: string\n  orderNo: string\n  packageName: string\n  replyContent: string\n  rechargeNo: string\n}\n\n// 问题反馈消息项\nexport type FeedbackMessageItem = {\n  sendType: string\n  time: string\n  replyContent: string\n  imgOssUrl: string\n}\n\n// 问题反馈详情\nexport type FeedbackDetail = {\n  id: number\n  feedbackNo: string\n  feedbackType: string\n  status: string\n  subTime: string\n  userPhone: string\n  imgOssUrl: string\n  feedbackContentList: FeedbackMessageItem[]\n  rechargeNo: string\n}"],"names":["UTS"],"mappings":";;MACY,kBAASA,cAAA,IAAA,QAAA;AAAA;;;;;;;;;;;;;;;;;;;;;;;;;;;;MAUT,oBAAWA,cAAA,IAAA,QAAA;AAAA;;;;;;;;;;;;;;;;;;;;MAMX,uBAAcA,cAAA,IAAA,QAAA;AAAA;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;MAed,4BAAmBA,cAAA,IAAA,QAAA;AAAA;;;;;;;;;;;;;;;;;;;;;;MAOnB,wBAAeA,cAAA,IAAA,QAAA;AAAA;;;;;;;;;;;;;;;;;;;;;;MAOf,iBAAQA,cAAA,IAAA,QAAA;AAAA;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;MAgBR,0BAAiBA,cAAA,IAAA,QAAA;AAAA;;;;;;;;;;;;;;;;;;MAKjB,iBAAQA,cAAA,IAAA,QAAA;AAAA;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;MAYR,sBAAaA,cAAA,IAAA,QAAA;AAAA;;;;;;;;;;;;;;;;;;;;;;MAMb,qBAAYA,cAAA,IAAA,QAAA;AAAA;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;MAkBZ,mBAAUA,cAAA,IAAA,QAAA;AAAA;;;;;;;;;;;;;;;;;;;;;;MAOV,iBAAQA,cAAA,IAAA,QAAA;AAAA;;;;;;;;;;;;;;;;;;MAKR,0BAAiBA,cAAA,IAAA,QAAA;AAAA;;;;;;;;;;;;;;;;;;;;MAKjB,oBAAWA,cAAA,IAAA,QAAA;AAAA;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;MAcX,gCAAuBA,cAAA,IAAA,QAAA;AAAA;;;;;;;;;;;;;;;;;;MAIvB,8BAAqBA,cAAA,IAAA,QAAA;AAAA;;;;;;;;;;;;;;;;;;;;;;;;MAOrB,yBAAgBA,cAAA,IAAA,QAAA;AAAA;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;MAYhB,eAAMA,cAAA,IAAA,QAAA;AAAA;;;;;;;;;;;;;;;;;;;;MAKN,gCAAuBA,cAAA,IAAA,QAAA;AAAA;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;MAwBvB,gCAAuBA,cAAA,IAAA,QAAA;AAAA;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;MAuBvB,qBAAYA,cAAA,IAAA,QAAA;AAAA;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;MAgBZ,4BAAmBA,cAAA,IAAA,QAAA;AAAA;;;;;;;;;;;;;;;;;;;;;;;;MAQnB,uBAAcA,cAAA,IAAA,QAAA;AAAA;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;"}
